CREATE TYPE "ScheduleType" AS ENUM ('DAILY', 'CUSTOM');
CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "timezone" TEXT NOT NULL DEFAULT 'UTC', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Habit" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "scheduleType" "ScheduleType" NOT NULL DEFAULT 'DAILY', "archivedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Habit_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HabitSchedule" ("id" TEXT NOT NULL, "habitId" TEXT NOT NULL, "weekday" INTEGER NOT NULL, CONSTRAINT "HabitSchedule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HabitCompletion" ("id" TEXT NOT NULL, "habitId" TEXT NOT NULL, "completionDate" DATE NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "HabitCompletion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RefreshToken" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "Habit_userId_archivedAt_idx" ON "Habit"("userId", "archivedAt"); CREATE INDEX "Habit_userId_name_idx" ON "Habit"("userId", "name"); CREATE UNIQUE INDEX "HabitSchedule_habitId_weekday_key" ON "HabitSchedule"("habitId", "weekday"); CREATE INDEX "HabitSchedule_habitId_idx" ON "HabitSchedule"("habitId"); CREATE UNIQUE INDEX "HabitCompletion_habitId_completionDate_key" ON "HabitCompletion"("habitId", "completionDate"); CREATE INDEX "HabitCompletion_habitId_completionDate_idx" ON "HabitCompletion"("habitId", "completionDate"); CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash"); CREATE INDEX "RefreshToken_userId_expiresAt_idx" ON "RefreshToken"("userId", "expiresAt");
ALTER TABLE "Habit" ADD CONSTRAINT "Habit_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "HabitSchedule" ADD CONSTRAINT "HabitSchedule_habitId_fkey" FOREIGN KEY ("habitId") REFERENCES "Habit"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "HabitCompletion" ADD CONSTRAINT "HabitCompletion_habitId_fkey" FOREIGN KEY ("habitId") REFERENCES "Habit"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
